begin;
lock table public.clinical_guidelines in share mode;
lock table public.guideline_versions in share row exclusive mode;
create temporary table population_batch on commit drop as
select * from jsonb_to_recordset($population$[{"id":"65fce08b-a289-44bd-9c91-79b2243f824c","title":"Dyslipidaemia and Atherosclerotic Risk","original_version_id":"65fce08b-a289-44bd-9c91-79b2243f824c","expected_hash":"282e677480e47cfbce54b054da4d1313","source_url":"https://www.nice.org.uk/guidance/ng238/chapter/recommendations","source_title":"Cardiovascular disease: risk assessment and reduction, including lipid modification","issuer":"NICE","scope":"Adults being assessed for primary or secondary prevention of cardiovascular disease; this limited extraction covers formal risk assessment, lipid and secondary-cause testing, selected statin decisions and monitoring.","content":{"id":"65fce08b-a289-44bd-9c91-79b2243f824c","title":"Dyslipidaemia and Atherosclerotic Risk","specialty":"Primary Care / Cardiology","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b005","lastReviewed":"2026-10-10","pillar":"Chronic Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Atherogenic lipoproteins contribute to plaque formation and progression. Absolute preventive benefit depends on baseline risk, lipid level, treatment intensity, competing risks, and patient preference. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Atherogenic lipoproteins contribute to plaque formation and progression. Absolute preventive benefit depends on baseline risk, lipid level, treatment intensity, competing risks, and patient preference.","Clinical expression and progression vary with baseline risk, comorbidity, treatment exposure, and access to timely care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Dyslipidaemia and Atherosclerotic Risk, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Acute chest pain or stroke symptoms","Severe lipid elevation with abdominal pain suggesting pancreatitis","Family history of premature vascular events","Tendon xanthomas or corneal arcus with very high LDL"]},"differentials":[{"condition":"Familial hypercholesterolaemia","distinguishingFeatures":"Marked LDL and family history support inherited-risk evaluation."},{"condition":"Secondary dyslipidaemia","distinguishingFeatures":"Diabetes, thyroid, renal/liver disease, alcohol, and medicines can contribute."},{"condition":"Laboratory variation","distinguishingFeatures":"Repeat or clarify sampling if result conflicts with clinical context."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Lipid profile and overall risk assessment; blood pressure, glycaemia, renal/liver/thyroid tests when indicated.","modalityTarget":"Lipid profile and overall risk assessment; blood pressure, glycaemia, renal/liver/thyroid tests when indicated. — Dyslipidaemia and Atherosclerotic Risk","targetCondition":"Dyslipidaemia and Atherosclerotic Risk","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Family history and prior vascular events inform risk categorisation and possible cascade assessment.","modalityTarget":"Family history and prior vascular events inform risk categorisation and possible cascade assessment. — Cause, complication, or risk relevant to Dyslipidaemia and Atherosclerotic Risk","targetCondition":"Cause, complication, or risk relevant to Dyslipidaemia and Atherosclerotic Risk","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Dyslipidaemia and Atherosclerotic Risk","targetCondition":"Important alternative to Dyslipidaemia and Atherosclerotic Risk","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults being assessed for primary or secondary prevention of cardiovascular disease; this limited extraction covers formal risk assessment, lipid and secondary-cause testing, selected statin decisions and monitoring. QRISK3 was developed for a UK population and must be reconciled with current Saudi cardiovascular-risk policy and population calibration. NICE supports atorvastatin 20 mg in defined groups but the recommendation text does not provide a complete route, frequency, duration, interaction and contraindication set, so no medication regimen is encoded. Pregnancy contraindication is recorded, but all current product information, liver, muscle, interaction and intolerance checks remain mandatory. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"715e9781-5834-4c11-884c-152e3a5fc752","title":"Cardiovascular disease: risk assessment and reduction, including lipid modification","issuer":"NICE","edition":"NG238, published 14 December 2023; recommendations retrieved 12 October 2026","url":"https://www.nice.org.uk/guidance/ng238/chapter/recommendations","locator":"Recommendations 1.1.8, 1.4.1 to 1.4.5, 1.5.1 to 1.5.10, 1.6.1 to 1.6.9 and 1.11.1 to 1.11.12","primary_source":true}],"selection_rationale":"Unverified scope: Adults being assessed for primary or secondary prevention of cardiovascular disease; this limited extraction covers formal risk assessment, lipid and secondary-cause testing, selected statin decisions and monitoring."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"QRISK3 10-year cardiovascular risk assessment","clinical_question":"What is the estimated 10-year cardiovascular risk in an adult without established cardiovascular disease?","expected_finding":"NICE recommends QRISK3 for people aged 25 to 84 without CVD and prioritises full assessment when estimated 10-year risk is 10% or more.","decision_rationale":"Formal risk assessment supports shared decisions on preventive treatment while recognising that risk may be underestimated in some people.","timeframe":"At preventive assessment; review estimates on an ongoing basis for people over 40"},{"test":"Full lipid profile and secondary-cause assessment","clinical_question":"What is the lipid pattern and is a secondary or familial disorder plausible?","expected_finding":"Measure total, HDL, non-HDL and triglyceride values and assess alcohol use, diabetes, thyroid disease, liver disease and nephrotic syndrome; use family history and findings to assess familial disease.","decision_rationale":"Secondary causes and familial dyslipidaemia alter treatment and referral.","timeframe":"Before lipid-lowering treatment"},{"test":"Baseline and follow-up safety testing","clinical_question":"Is statin treatment safe and achieving the expected lipid response?","expected_finding":"Baseline assessment includes diabetes status, renal function and transaminases; repeat full lipid profile and transaminases 2 to 3 months after starting or changing treatment, and transaminases at 12 months.","decision_rationale":"Monitoring checks response and identifies clinically important adverse effects.","timeframe":"Baseline, 2 to 3 months after starting or changing treatment, and transaminases at 12 months"}],"evidence":{"sources":[{"id":"715e9781-5834-4c11-884c-152e3a5fc752","title":"Cardiovascular disease: risk assessment and reduction, including lipid modification","issuer":"NICE","edition":"NG238, published 14 December 2023; recommendations retrieved 12 October 2026","url":"https://www.nice.org.uk/guidance/ng238/chapter/recommendations","locator":"Recommendations 1.1.8, 1.4.1 to 1.4.5, 1.5.1 to 1.5.10, 1.6.1 to 1.6.9 and 1.11.1 to 1.11.12","primary_source":true}],"selection_rationale":"Unverified scope: Adults being assessed for primary or secondary prevention of cardiovascular disease; this limited extraction covers formal risk assessment, lipid and secondary-cause testing, selected statin decisions and monitoring."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Use shared decision-making after lifestyle and modifiable-risk review; NICE recommends atorvastatin 20 mg for primary prevention when 10-year QRISK3 is 10% or more and allows consideration below that threshold when risk may be underestimated or the person prefers treatment.","timeframe":"After baseline assessment"},{"instruction":"Do not use statins during pregnancy; stop if pregnancy is possible, stop 3 months before attempting conception and do not restart until breastfeeding is finished.","timeframe":"Before prescribing and throughout treatment"},{"instruction":"Review gaps: QRISK3 was developed for a UK population and must be reconciled with current Saudi cardiovascular-risk policy and population calibration. NICE supports atorvastatin 20 mg in defined groups but the recommendation text does not provide a complete route, frequency, duration, interaction and contraindication set, so no medication regimen is encoded. Pregnancy contraindication is recorded, but all current product information, liver, muscle, interaction and intolerance checks remain mandatory. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"715e9781-5834-4c11-884c-152e3a5fc752","title":"Cardiovascular disease: risk assessment and reduction, including lipid modification","issuer":"NICE","edition":"NG238, published 14 December 2023; recommendations retrieved 12 October 2026","url":"https://www.nice.org.uk/guidance/ng238/chapter/recommendations","locator":"Recommendations 1.1.8, 1.4.1 to 1.4.5, 1.5.1 to 1.5.10, 1.6.1 to 1.6.9 and 1.11.1 to 1.11.12","primary_source":true}],"selection_rationale":"Unverified scope: Adults being assessed for primary or secondary prevention of cardiovascular disease; this limited extraction covers formal risk assessment, lipid and secondary-cause testing, selected statin decisions and monitoring."}}]},"nonClinicalManagement":{"patientEducation":["Explain dyslipidaemia and atherosclerotic risk in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Primary Care / Cardiology","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"d47f0125-8e64-4b93-8c72-9f16a4d0e738","title":"Elective Cholecystectomy Pre-operative Assessment Pathway","original_version_id":"d47f0125-8e64-4b93-8c72-9f16a4d0e738","expected_hash":"1df32e0c8dbdd9a57999ac2128d358e2","source_url":"https://www.nice.org.uk/guidance/ng45/chapter/recommendations","source_title":"Routine preoperative tests for elective surgery","issuer":"NICE","scope":"Adults over 16 preparing for elective non-cardiothoracic surgery; this limited extraction applies the NICE preoperative-test framework to elective cholecystectomy after the local team assigns procedure grade and ASA class.","content":{"id":"d47f0125-8e64-4b93-8c72-9f16a4d0e738","title":"Elective Cholecystectomy Pre-operative Assessment Pathway","specialty":"General Surgery and Anaesthesia","authority":"MOH","status":"draft","version":"official-extraction-2026-10-11-b005","lastReviewed":"2026-10-10","pillar":"Planned Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Gallstones may cause biliary colic or complications including cholecystitis, choledocholithiasis, or pancreatitis. This pathway supports pre-operative review after a decision for elective cholecystectomy.","keyMechanisms":["Gallstone formation from altered bile composition or gallbladder emptying","Transient cystic-duct obstruction causing biliary pain","Persistent obstruction or ductal migration causing inflammation or cholestasis"]},"presentation":{"symptoms":["Episodic right-upper-quadrant or epigastric pain, sometimes after meals","Possible nausea or vomiting during biliary colic","Known symptomatic gallstones with a documented surgical plan"],"physicalSigns":["Often normal between episodes","Possible right-upper-quadrant tenderness","Jaundice, fever, or marked tenderness suggests complication and needs reassessment"],"redFlags":["Fever, persistent pain, or systemic illness","Jaundice, dark urine, pale stools, or suspected duct obstruction","Severe persistent epigastric pain radiating to the back","Pregnancy, anticoagulation, or significant cardiopulmonary instability requiring modified planning"]},"differentials":[{"condition":"Acute cholecystitis","distinguishingFeatures":"Persistent right-upper-quadrant pain and tenderness, often with fever or inflammatory findings."},{"condition":"Choledocholithiasis or cholangitis","distinguishingFeatures":"Jaundice or cholestatic laboratory pattern; fever and systemic illness raise concern for cholangitis."},{"condition":"Acute pancreatitis","distinguishingFeatures":"Persistent severe epigastric pain, often radiating to back, with supportive enzyme findings."},{"condition":"Peptic, hepatic, or cardiac cause","distinguishingFeatures":"Alternative history, examination, ECG, or laboratory findings; investigate atypical symptoms."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Review prior abdominal ultrasonography","modalityTarget":"Review prior abdominal ultrasonography — Gallstones supporting elective indication","targetCondition":"Gallstones supporting elective indication","expectedFinding":"Gallstones or relevant gallbladder findings consistent with history","clinicalRationale":"Confirm available imaging and indication; repeat only when warranted."},{"tier":"laboratory","testName":"Liver function tests","modalityTarget":"Liver function tests — Possible common bile-duct obstruction","targetCondition":"Possible common bile-duct obstruction","expectedFinding":"Cholestatic or other abnormal pattern requiring evaluation","clinicalRationale":"Identify findings that may change operative planning or require ductal assessment."},{"tier":"laboratory","testName":"Complete blood count and inflammatory markers when indicated","modalityTarget":"Complete blood count and inflammatory markers when indicated — Intercurrent inflammation or infection","targetCondition":"Intercurrent inflammation or infection","expectedFinding":"Inflammatory abnormality interpreted with symptoms and examination","clinicalRationale":"Identify acute complications that make routine scheduling inappropriate."},{"tier":"laboratory","testName":"Pregnancy test when appropriate and with consent","modalityTarget":"Pregnancy test when appropriate and with consent — Pregnancy affecting perioperative planning","targetCondition":"Pregnancy affecting perioperative planning","expectedFinding":"Positive result prompting pregnancy-specific shared planning","clinicalRationale":"Adapt elective timing and anaesthetic planning."}],"ruleOut":[{"tier":"laboratory","testName":"Clinical review, liver tests, and targeted ductal imaging when indicated","modalityTarget":"Clinical review, liver tests, and targeted ductal imaging when indicated — Common bile-duct stone or obstruction","targetCondition":"Common bile-duct stone or obstruction","expectedFinding":"No clinical, biochemical, or imaging evidence of obstruction","clinicalRationale":"Further testing depends on local risk criteria and overall assessment."},{"tier":"laboratory","testName":"Clinical assessment and inflammatory investigations when indicated","modalityTarget":"Clinical assessment and inflammatory investigations when indicated — Acute cholecystitis or cholangitis","targetCondition":"Acute cholecystitis or cholangitis","expectedFinding":"No persistent inflammatory symptoms or supportive findings","clinicalRationale":"Identify acute disease requiring urgent rather than elective management."},{"tier":"laboratory","testName":"Anaesthetic assessment and targeted cardiopulmonary investigations","modalityTarget":"Anaesthetic assessment and targeted cardiopulmonary investigations — Perioperative risk requiring optimisation","targetCondition":"Perioperative risk requiring optimisation","expectedFinding":"No unresolved active condition making the procedure unsafe at this time","clinicalRationale":"Select tests based on history, examination, functional status, and local guidance."}]},"clinicalManagement":[{"id":"chole-1","title":"Confirm indication and exclude acute complication","timeframe":"At surgical review and again if symptoms change","actions":["Confirm symptoms, imaging, indication, and informed preference.","Review comorbidities, medicines, allergies, anticoagulants, and anaesthetic history.","Assess for fever, persistent pain, jaundice, pancreatitis, or other acute complication.","Plan further biliary assessment if history, laboratory results, or imaging indicate."],"branches":[{"condition":"Acute cholecystitis, cholangitis, pancreatitis, or ductal obstruction suspected","actions":["Pause routine elective preparation and arrange urgent reassessment.","Use the locally approved acute biliary pathway."]},{"condition":"Elective indication remains appropriate without acute complication","actions":["Proceed with pre-operative assessment and shared decision-making.","Confirm procedure, consent, and expected care pathway."]}]},{"id":"chole-2","title":"Optimise and complete anaesthetic review","timeframe":"Before scheduled procedure","actions":["Complete history, examination, and investigations based on patient risk and local policy.","Review anticoagulants, antiplatelets, diabetes medicines, allergies, and other medicines with the responsible clinician.","Optimise active conditions and discuss anaesthetic risk, fasting, and perioperative expectations.","Assess thrombosis-prevention and infection-prevention needs under local protocols."],"branches":[{"condition":"Uncontrolled comorbidity, infection, or important new abnormality","actions":["Discuss optimisation, further testing, or postponement with surgery and anaesthesia.","Communicate the revised plan and safety-net advice."]},{"condition":"Pregnancy confirmed or suspected","actions":["Arrange obstetric, surgical, and anaesthetic discussion.","Reassess timing and necessity through shared decisions and local policy."]}]},{"id":"chole-3","title":"Confirm readiness and hand over","timeframe":"Day of surgery","actions":["Confirm identity, procedure, consent, allergies, fasting, results, and perioperative plan.","Reassess interval symptoms and vital signs.","Confirm team, equipment, and post-operative disposition.","Document handover and deviations from plan."],"branches":[{"condition":"New jaundice, fever, persistent severe pain, or instability","actions":["Stop routine elective progression and request urgent senior review.","Reassess for biliary complication or alternative acute diagnosis."]},{"condition":"Checks satisfactory and patient remains appropriate","actions":["Proceed under the approved surgical and anaesthetic plan.","Provide post-operative instructions and follow-up arrangements."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults over 16 preparing for elective non-cardiothoracic surgery; this limited extraction applies the NICE preoperative-test framework to elective cholecystectomy after the local team assigns procedure grade and ASA class. NICE NG45 is a 2016 UK testing guideline and does not replace a cholecystectomy-specific history, examination, imaging review, indication check, anaesthetic assessment, bile-duct evaluation, thrombosis plan or current Saudi perioperative protocol. Laparoscopic versus open procedure grade must be assigned locally. No antimicrobial, analgesic, anticoagulant or other medicine regimen is verified. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"2c333586-336f-43ee-b6e0-51307a6422d6","title":"Routine preoperative tests for elective surgery","issuer":"NICE","edition":"NG45, published 5 April 2016","url":"https://www.nice.org.uk/guidance/ng45/chapter/recommendations","locator":"Recommendations 1.1 to 1.7 and Tables 1 to 3 for minor, intermediate and major or complex surgery by ASA grade","primary_source":true}],"selection_rationale":"Unverified scope: Adults over 16 preparing for elective non-cardiothoracic surgery; this limited extraction applies the NICE preoperative-test framework to elective cholecystectomy after the local team assigns procedure grade and ASA class."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Procedure grade and ASA physical-status assessment","clinical_question":"Which NICE testing table applies to the planned procedure and the person's comorbidity burden?","expected_finding":"NICE selects routine tests by minor, intermediate or major/complex surgery and ASA grade rather than ordering a universal panel.","decision_rationale":"Test need changes with surgical magnitude and systemic disease.","timeframe":"At preoperative assessment before ordering tests"},{"test":"Full blood count, kidney function and resting ECG as indicated","clinical_question":"Which tests are supported by the assigned surgery and ASA category?","expected_finding":"Use the NICE tables: requirements range from not routine to consider or offer according to surgery grade, ASA status and cardiovascular, renal or diabetes comorbidity.","decision_rationale":"The table-based approach reduces unnecessary testing while detecting abnormalities likely to alter perioperative care.","timeframe":"During preoperative assessment, using recent valid results when appropriate"},{"test":"HbA1c in known diabetes","clinical_question":"Is recent glycaemic assessment available for a person with diabetes?","expected_finding":"Include the latest HbA1c in the referral and offer testing if it has not been measured in the previous 3 months; do not routinely test people without diagnosed diabetes.","decision_rationale":"Recent glycaemic status informs perioperative planning without screening every surgical patient.","timeframe":"Within 3 months before surgery for people with diabetes"}],"evidence":{"sources":[{"id":"2c333586-336f-43ee-b6e0-51307a6422d6","title":"Routine preoperative tests for elective surgery","issuer":"NICE","edition":"NG45, published 5 April 2016","url":"https://www.nice.org.uk/guidance/ng45/chapter/recommendations","locator":"Recommendations 1.1 to 1.7 and Tables 1 to 3 for minor, intermediate and major or complex surgery by ASA grade","primary_source":true}],"selection_rationale":"Unverified scope: Adults over 16 preparing for elective non-cardiothoracic surgery; this limited extraction applies the NICE preoperative-test framework to elective cholecystectomy after the local team assigns procedure grade and ASA class."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Carry forward relevant test results already obtained in primary care and avoid duplicating valid investigations.","timeframe":"At surgical referral and preoperative review"},{"instruction":"If anticoagulant treatment needs modification, create an individualised perioperative plan using current local guidance; routine coagulation tests do not measure direct oral anticoagulant effect.","timeframe":"Before surgery"},{"instruction":"Review gaps: NICE NG45 is a 2016 UK testing guideline and does not replace a cholecystectomy-specific history, examination, imaging review, indication check, anaesthetic assessment, bile-duct evaluation, thrombosis plan or current Saudi perioperative protocol. Laparoscopic versus open procedure grade must be assigned locally. No antimicrobial, analgesic, anticoagulant or other medicine regimen is verified. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"2c333586-336f-43ee-b6e0-51307a6422d6","title":"Routine preoperative tests for elective surgery","issuer":"NICE","edition":"NG45, published 5 April 2016","url":"https://www.nice.org.uk/guidance/ng45/chapter/recommendations","locator":"Recommendations 1.1 to 1.7 and Tables 1 to 3 for minor, intermediate and major or complex surgery by ASA grade","primary_source":true}],"selection_rationale":"Unverified scope: Adults over 16 preparing for elective non-cardiothoracic surgery; this limited extraction applies the NICE preoperative-test framework to elective cholecystectomy after the local team assigns procedure grade and ASA class."}}]},"nonClinicalManagement":{"patientEducation":["Explain indication, alternatives, material risks, and expected recovery using approved surgical information.","Give fasting, arrival, medicine-review, and pre-operative contact instructions.","Advise prompt review for fever, jaundice, or persistent severe pain."],"lifestyleAndDiet":["Offer balanced eating and symptom-aware meal advice while awaiting surgery.","Encourage smoking cessation and feasible general-health optimisation."],"mdtReferrals":["General surgery","Anaesthesia","Primary care or relevant specialist for optimisation","Obstetrics if pregnant or pregnancy suspected","Hepatobiliary service when ductal disease is suspected"],"dischargeCriteria":["Assessment and consent are complete and documented.","Acute complications and significant unoptimised conditions have been addressed.","Patient has preparation instructions and contact details for worsening symptoms."],"followUpPlan":"Confirm pre-operative review and procedure arrangements; after surgery follow the operating team's wound, pathology, recovery, and escalation instructions."}}},{"id":"c5e62cae-fb6e-47ef-8681-bec748e64dd4","title":"Elective Coronary Revascularisation Review","original_version_id":"c5e62cae-fb6e-47ef-8681-bec748e64dd4","expected_hash":"8a8884a95504171fa5ae9d0feb4d14b5","source_url":"https://www.nice.org.uk/guidance/cg126/chapter/Recommendations","source_title":"Stable angina: management","issuer":"NICE","scope":"Adults with stable angina being considered for elective coronary revascularisation; this limited extraction covers persistent symptoms, coronary anatomy, functional assessment, multidisciplinary review and CABG versus PCI decisions.","content":{"id":"c5e62cae-fb6e-47ef-8681-bec748e64dd4","title":"Elective Coronary Revascularisation Review","specialty":"Cardiology / Cardiothoracic Surgery","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b005","lastReviewed":"2026-10-10","pillar":"Planned Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Coronary atherosclerosis may limit perfusion and cause angina or myocardial injury. Revascularisation can improve symptoms or selected prognostic outcomes; choice depends on anatomy, comorbidity, guideline evidence, and patient preference. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Coronary atherosclerosis may limit perfusion and cause angina or myocardial injury. Revascularisation can improve symptoms or selected prognostic outcomes","choice depends on anatomy, comorbidity, guideline evidence, and patient preference."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Elective Coronary Revascularisation Review, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Acute coronary syndrome or rest pain","Decompensated heart failure","Unstable arrhythmia or severe renal injury","Active infection before an elective procedure"]},"differentials":[{"condition":"Non-cardiac chest pain","distinguishingFeatures":"Reassess symptoms and objective evidence."},{"condition":"Microvascular angina","distinguishingFeatures":"Epicardial anatomy may not fully explain symptoms."},{"condition":"Vasospastic disease","distinguishingFeatures":"Pattern and response differ; specialist review may be needed."}],"investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"ECG, echocardiography, coronary anatomy and ischaemia evidence; renal function, blood count and surgical risk assessment.","modalityTarget":"ECG, echocardiography, coronary anatomy and ischaemia evidence; renal function, blood count and surgical risk assessment. — Elective Coronary Revascularisation Review","targetCondition":"Elective Coronary Revascularisation Review","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Review prior antiplatelet, anticoagulant, contrast exposure, diabetes and patient-reported function.","modalityTarget":"Review prior antiplatelet, anticoagulant, contrast exposure, diabetes and patient-reported function. — Cause, complication, or risk relevant to Elective Coronary Revascularisation Review","targetCondition":"Cause, complication, or risk relevant to Elective Coronary Revascularisation Review","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Elective Coronary Revascularisation Review","targetCondition":"Important alternative to Elective Coronary Revascularisation Review","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults with stable angina being considered for elective coronary revascularisation; this limited extraction covers persistent symptoms, coronary anatomy, functional assessment, multidisciplinary review and CABG versus PCI decisions. This older UK guideline requires reconciliation with current ESC, ACC/AHA and Saudi revascularisation guidance, contemporary physiology and intravascular-imaging practice, stent technology, diabetes evidence and surgical-risk tools. It does not verify antiplatelet, anticoagulant, antianginal, lipid-lowering or peri-procedural regimens. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"d0692986-24f2-446c-b0e9-4b847e2d8fd4","title":"Stable angina: management","issuer":"NICE","edition":"CG126, published 23 July 2011; last updated 25 August 2016","url":"https://www.nice.org.uk/guidance/cg126/chapter/Recommendations","locator":"Recommendations 1.5.1 to 1.5.14: investigation and revascularisation","primary_source":true}],"selection_rationale":"Unverified scope: Adults with stable angina being considered for elective coronary revascularisation; this limited extraction covers persistent symptoms, coronary anatomy, functional assessment, multidisciplinary review and CABG versus PCI decisions."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Symptom and optimal-medical-treatment review","clinical_question":"Are stable-angina symptoms satisfactorily controlled and is the diagnosis still secure?","expected_finding":"Persistent symptoms despite optimal medical treatment are a NICE indication to consider revascularisation.","decision_rationale":"Revascularisation for stable angina is selected in relation to symptom burden, treatment response and prognostic anatomy.","timeframe":"Before invasive strategy selection"},{"test":"Coronary angiography with functional assessment when required","clinical_question":"What is the coronary anatomy and does a lesion explain clinically important ischaemia?","expected_finding":"NICE recommends coronary angiography to guide strategy when symptoms remain uncontrolled; additional non-invasive or invasive functional testing may be required.","decision_rationale":"Anatomy and functional significance guide whether CABG, PCI or continued medical treatment is appropriate.","timeframe":"Before revascularisation decision"},{"test":"Systematic anatomic and clinical complexity assessment","clinical_question":"Do left-main, proximal three-vessel or complex multivessel disease and comorbidities favour CABG or PCI?","expected_finding":"Assess coronary severity and complexity with diabetes, age, comorbidities and procedural suitability.","decision_rationale":"NICE identifies potential CABG survival advantage in selected multivessel disease and requires individual risk-benefit comparison.","timeframe":"At multidisciplinary review"}],"evidence":{"sources":[{"id":"d0692986-24f2-446c-b0e9-4b847e2d8fd4","title":"Stable angina: management","issuer":"NICE","edition":"CG126, published 23 July 2011; last updated 25 August 2016","url":"https://www.nice.org.uk/guidance/cg126/chapter/Recommendations","locator":"Recommendations 1.5.1 to 1.5.14: investigation and revascularisation","primary_source":true}],"selection_rationale":"Unverified scope: Adults with stable angina being considered for elective coronary revascularisation; this limited extraction covers persistent symptoms, coronary anatomy, functional assessment, multidisciplinary review and CABG versus PCI decisions."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Discuss complex anatomy, left-main disease, anatomically complex three-vessel disease or uncertain strategy in a team including cardiac surgeons and interventional cardiologists.","timeframe":"Before final strategy"},{"instruction":"Give balanced information on continued medical treatment, CABG and PCI, including symptom relief, procedural risks, repeat-revascularisation likelihood and possible survival advantage in selected disease.","timeframe":"Before consent"},{"instruction":"Review gaps: This older UK guideline requires reconciliation with current ESC, ACC/AHA and Saudi revascularisation guidance, contemporary physiology and intravascular-imaging practice, stent technology, diabetes evidence and surgical-risk tools. It does not verify antiplatelet, anticoagulant, antianginal, lipid-lowering or peri-procedural regimens. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"d0692986-24f2-446c-b0e9-4b847e2d8fd4","title":"Stable angina: management","issuer":"NICE","edition":"CG126, published 23 July 2011; last updated 25 August 2016","url":"https://www.nice.org.uk/guidance/cg126/chapter/Recommendations","locator":"Recommendations 1.5.1 to 1.5.14: investigation and revascularisation","primary_source":true}],"selection_rationale":"Unverified scope: Adults with stable angina being considered for elective coronary revascularisation; this limited extraction covers persistent symptoms, coronary anatomy, functional assessment, multidisciplinary review and CABG versus PCI decisions."}}]},"nonClinicalManagement":{"patientEducation":["Explain elective coronary revascularisation review in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Cardiology / Cardiothoracic Surgery","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"2ebb8b8e-91bd-44ef-98f9-24daa70738d4","title":"Elective Hernia Repair Assessment","original_version_id":"2ebb8b8e-91bd-44ef-98f9-24daa70738d4","expected_hash":"ed6d0c92fd3bad300bc32d74900e8a14","source_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10588975/","source_title":"Update of the international HerniaSurge guidelines for groin hernia management","issuer":"Other","scope":"Adults with groin hernia being assessed for elective repair; this limited extraction covers symptom and hernia-characteristic review, shared decisions on repair approach, mesh considerations and watchful-waiting evidence for asymptomatic or minimally symptomatic men.","content":{"id":"2ebb8b8e-91bd-44ef-98f9-24daa70738d4","title":"Elective Hernia Repair Assessment","specialty":"General Surgery","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b005","lastReviewed":"2026-10-10","pillar":"Planned Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Abdominal wall weakness allows tissue or viscera to protrude; symptoms range from incidental bulge to incarceration or strangulation. Repair choice depends on anatomy, symptoms, operative risk, and patient preference. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Abdominal wall weakness allows tissue or viscera to protrude","symptoms range from incidental bulge to incarceration or strangulation. Repair choice depends on anatomy, symptoms, operative risk, and patient preference."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Elective Hernia Repair Assessment, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Irreducible painful bulge with vomiting","Skin change, fever, or bowel obstruction","Acute testicular pain or vascular compromise","Rapid enlargement or unclear diagnosis"]},"differentials":[{"condition":"Lymphadenopathy","distinguishingFeatures":"Examination and ultrasound may distinguish from hernia."},{"condition":"Femoral aneurysm or vascular mass","distinguishingFeatures":"Pulsatility requires vascular assessment."},{"condition":"Hydrocele or scrotal mass","distinguishingFeatures":"Anatomy and imaging clarify diagnosis."}],"investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Focused groin and abdominal examination standing and supine; ultrasound when diagnosis or anatomy is unclear.","modalityTarget":"Focused groin and abdominal examination standing and supine; ultrasound when diagnosis or anatomy is unclear. — Elective Hernia Repair Assessment","targetCondition":"Elective Hernia Repair Assessment","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Preoperative review of comorbidity, medicines, smoking, cough, anticoagulation and recovery supports.","modalityTarget":"Preoperative review of comorbidity, medicines, smoking, cough, anticoagulation and recovery supports. — Cause, complication, or risk relevant to Elective Hernia Repair Assessment","targetCondition":"Cause, complication, or risk relevant to Elective Hernia Repair Assessment","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Elective Hernia Repair Assessment","targetCondition":"Important alternative to Elective Hernia Repair Assessment","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults with groin hernia being assessed for elective repair; this limited extraction covers symptom and hernia-characteristic review, shared decisions on repair approach, mesh considerations and watchful-waiting evidence for asymptomatic or minimally symptomatic men. This international society update supplements rather than replaces the 2018 HerniaSurge guideline and is focused on selected updated questions. It does not establish a complete preoperative test panel or cover all ventral, incisional, paediatric, strangulated or obstructed hernias. Current Saudi surgical pathways, surgeon expertise, female femoral-hernia risk, anaesthetic assessment and local device governance require reconciliation. No medicine regimen is verified. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"ad17e661-7a01-489d-be68-b9a5db469f74","title":"Update of the international HerniaSurge guidelines for groin hernia management","issuer":"Other","edition":"HerniaSurge update, published 20 October 2023","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10588975/","locator":"Updated statements and recommendations in Chapters 6a-b, 6d, 6f, 7 and 8; sections on mesh versus non-mesh repair, approach selection and occult contralateral hernia","primary_source":true}],"selection_rationale":"Unverified scope: Adults with groin hernia being assessed for elective repair; this limited extraction covers symptom and hernia-characteristic review, shared decisions on repair approach, mesh considerations and watchful-waiting evidence for asymptomatic or minimally symptomatic men."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Structured hernia history and physical examination","clinical_question":"Are symptoms, reducibility, functional impact, acute warning features and prior repairs defined?","expected_finding":"Assessment should distinguish elective groin hernia from acutely symptomatic disease and document patient and hernia characteristics that influence approach.","decision_rationale":"Urgency and repair method depend on symptoms, anatomy, prior surgery and patient factors.","timeframe":"At surgical assessment"},{"test":"Assessment for occult or contralateral groin hernia","clinical_question":"Is there a clinically occult contralateral hernia and would identifying it change the agreed plan?","expected_finding":"Occult contralateral hernia management has uncertain natural history and should be addressed through informed discussion rather than automatic repair.","decision_rationale":"Repair can prevent later surgery but exposes an asymptomatic side to procedural risk.","timeframe":"Before or during minimally invasive repair planning"},{"test":"Patient and hernia suitability for mesh, non-mesh, open or laparo-endoscopic repair","clinical_question":"Which approach best fits anatomy, infection risk, preferences and available expertise?","expected_finding":"Mesh repair is recommended for most adults because recurrence is lower; selected people may choose non-mesh repair when expertise is available, and infection can contraindicate permanent mesh.","decision_rationale":"Technique selection balances recurrence, pain, rare mesh complications and surgeon competence.","timeframe":"Before listing and consent"}],"evidence":{"sources":[{"id":"ad17e661-7a01-489d-be68-b9a5db469f74","title":"Update of the international HerniaSurge guidelines for groin hernia management","issuer":"Other","edition":"HerniaSurge update, published 20 October 2023","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10588975/","locator":"Updated statements and recommendations in Chapters 6a-b, 6d, 6f, 7 and 8; sections on mesh versus non-mesh repair, approach selection and occult contralateral hernia","primary_source":true}],"selection_rationale":"Unverified scope: Adults with groin hernia being assessed for elective repair; this limited extraction covers symptom and hernia-characteristic review, shared decisions on repair approach, mesh considerations and watchful-waiting evidence for asymptomatic or minimally symptomatic men."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Use shared decision-making to explain mesh and non-mesh options, recurrence, chronic pain, sexual symptoms, rare visceral complications and the experience of the operating team.","timeframe":"Before consent"},{"instruction":"For asymptomatic or minimally symptomatic inguinal hernia in men, discuss watchful waiting as an option while explaining that many people later cross over to surgery because of symptoms.","timeframe":"At elective management decision"},{"instruction":"Review gaps: This international society update supplements rather than replaces the 2018 HerniaSurge guideline and is focused on selected updated questions. It does not establish a complete preoperative test panel or cover all ventral, incisional, paediatric, strangulated or obstructed hernias. Current Saudi surgical pathways, surgeon expertise, female femoral-hernia risk, anaesthetic assessment and local device governance require reconciliation. No medicine regimen is verified. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"ad17e661-7a01-489d-be68-b9a5db469f74","title":"Update of the international HerniaSurge guidelines for groin hernia management","issuer":"Other","edition":"HerniaSurge update, published 20 October 2023","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10588975/","locator":"Updated statements and recommendations in Chapters 6a-b, 6d, 6f, 7 and 8; sections on mesh versus non-mesh repair, approach selection and occult contralateral hernia","primary_source":true}],"selection_rationale":"Unverified scope: Adults with groin hernia being assessed for elective repair; this limited extraction covers symptom and hernia-characteristic review, shared decisions on repair approach, mesh considerations and watchful-waiting evidence for asymptomatic or minimally symptomatic men."}}]},"nonClinicalManagement":{"patientEducation":["Explain elective hernia repair assessment in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["General Surgery","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"090cabb1-daef-487b-a0cf-4f36c4e6fb30","title":"Elective Hip and Knee Arthroplasty Preparation","original_version_id":"090cabb1-daef-487b-a0cf-4f36c4e6fb30","expected_hash":"392c776ebdeb990ff0737c6f23c51d15","source_url":"https://www.nice.org.uk/guidance/ng157/chapter/Recommendations","source_title":"Joint replacement (primary): hip, knee and shoulder","issuer":"NICE","scope":"Adults offered primary elective hip or knee replacement; this limited extraction covers shared decisions, preparation information and preoperative rehabilitation.","content":{"id":"090cabb1-daef-487b-a0cf-4f36c4e6fb30","title":"Elective Hip and Knee Arthroplasty Preparation","specialty":"Orthopaedics","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b005","lastReviewed":"2026-10-10","pillar":"Planned Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Advanced joint degeneration produces pain, stiffness, and impaired function; arthroplasty may improve pain and mobility in selected patients. Outcomes depend on comorbidity optimisation, infection prevention, rehabilitation, and patient expectations. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Advanced joint degeneration produces pain, stiffness, and impaired function","arthroplasty may improve pain and mobility in selected patients. Outcomes depend on comorbidity optimisation, infection prevention, rehabilitation, and patient expectations."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Elective Hip and Knee Arthroplasty Preparation, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Active infection or skin lesion near operative site","Unstable cardiac/pulmonary disease","Uncontrolled glycaemia or severe anaemia needing optimisation","New calf swelling or acute joint change before surgery"]},"differentials":[{"condition":"Referred hip/spine pain","distinguishingFeatures":"Examination and imaging should confirm symptom source."},{"condition":"Inflammatory arthritis","distinguishingFeatures":"May alter procedure and perioperative medicines."},{"condition":"Central pain or severe frailty","distinguishingFeatures":"May affect expected benefit and rehabilitation plan."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Clinical history, functional assessment, joint imaging, blood count, renal/metabolic tests and anaesthetic risk review as indicated.","modalityTarget":"Clinical history, functional assessment, joint imaging, blood count, renal/metabolic tests and anaesthetic risk review as indicated. — Elective Hip and Knee Arthroplasty Preparation","targetCondition":"Elective Hip and Knee Arthroplasty Preparation","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Screen infection, medication, nutrition, mobility, fall, and thrombosis risks using local pre-op pathway.","modalityTarget":"Screen infection, medication, nutrition, mobility, fall, and thrombosis risks using local pre-op pathway. — Cause, complication, or risk relevant to Elective Hip and Knee Arthroplasty Preparation","targetCondition":"Cause, complication, or risk relevant to Elective Hip and Knee Arthroplasty Preparation","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Elective Hip and Knee Arthroplasty Preparation","targetCondition":"Important alternative to Elective Hip and Knee Arthroplasty Preparation","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults offered primary elective hip or knee replacement; this limited extraction covers shared decisions, preparation information and preoperative rehabilitation. This UK guideline must be reconciled with current Saudi arthroplasty pathways, implant governance, blood management, venous-thromboembolism prevention, infection prevention, anaesthetic assessment, dental policy and local rehabilitation capacity. It is not a complete surgical eligibility or optimisation protocol and no medicine regimen is verified. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"71fb9541-f45e-4f14-9ab7-1daed8a0db13","title":"Joint replacement (primary): hip, knee and shoulder","issuer":"NICE","edition":"NG157, published 4 June 2020","url":"https://www.nice.org.uk/guidance/ng157/chapter/Recommendations","locator":"Recommendations 1.1.1 to 1.1.4 and 1.2.1; sections on shared decision-making, information and preoperative rehabilitation","primary_source":true}],"selection_rationale":"Unverified scope: Adults offered primary elective hip or knee replacement; this limited extraction covers shared decisions, preparation information and preoperative rehabilitation."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Shared-decision and expectation assessment","clinical_question":"Does the person understand alternatives, likely benefits, procedural risks, implant choices and possible future surgery?","expected_finding":"NICE requires procedure-specific information and discussion of alternatives, anaesthesia, analgesia, recovery and rehabilitation.","decision_rationale":"Expectations, preferences and informed consent shape whether and how joint replacement proceeds.","timeframe":"From the first surgical appointment and throughout preparation"},{"test":"Preoperative rehabilitation needs assessment","clinical_question":"Which exercise, functional, lifestyle or support needs could affect recovery?","expected_finding":"Assess exercise capacity, independence, weight-management needs, diet, smoking and barriers to postoperative rehabilitation.","decision_rationale":"Preoperative advice prepares the person for surgery and engagement in recovery.","timeframe":"When listed for hip or knee replacement"}],"evidence":{"sources":[{"id":"71fb9541-f45e-4f14-9ab7-1daed8a0db13","title":"Joint replacement (primary): hip, knee and shoulder","issuer":"NICE","edition":"NG157, published 4 June 2020","url":"https://www.nice.org.uk/guidance/ng157/chapter/Recommendations","locator":"Recommendations 1.1.1 to 1.1.4 and 1.2.1; sections on shared decision-making, information and preoperative rehabilitation","primary_source":true}],"selection_rationale":"Unverified scope: Adults offered primary elective hip or knee replacement; this limited extraction covers shared decisions, preparation information and preoperative rehabilitation."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Give advice on exercises to perform before and after surgery, lifestyle measures including weight management, diet and smoking cessation, and maximising functional independence and quality of life.","timeframe":"During preoperative preparation"},{"instruction":"Provide clear information on hospital stay, pain, wound care, rehabilitation, return to work and return to usual activities, with a contact route for questions.","timeframe":"Before surgery and reinforced as needed"},{"instruction":"Review gaps: This UK guideline must be reconciled with current Saudi arthroplasty pathways, implant governance, blood management, venous-thromboembolism prevention, infection prevention, anaesthetic assessment, dental policy and local rehabilitation capacity. It is not a complete surgical eligibility or optimisation protocol and no medicine regimen is verified. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"71fb9541-f45e-4f14-9ab7-1daed8a0db13","title":"Joint replacement (primary): hip, knee and shoulder","issuer":"NICE","edition":"NG157, published 4 June 2020","url":"https://www.nice.org.uk/guidance/ng157/chapter/Recommendations","locator":"Recommendations 1.1.1 to 1.1.4 and 1.2.1; sections on shared decision-making, information and preoperative rehabilitation","primary_source":true}],"selection_rationale":"Unverified scope: Adults offered primary elective hip or knee replacement; this limited extraction covers shared decisions, preparation information and preoperative rehabilitation."}}]},"nonClinicalManagement":{"patientEducation":["Explain elective hip and knee arthroplasty preparation in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Orthopaedics","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"78cec019-7976-489a-a4c9-fdd6f7c316c7","title":"Elective Hysterectomy for Benign Disease","original_version_id":"78cec019-7976-489a-a4c9-fdd6f7c316c7","expected_hash":"30e74f3801d1ec3ef5ca0b52e456d1fc","source_url":"https://www.nice.org.uk/guidance/ng88/chapter/Recommendations","source_title":"Heavy menstrual bleeding: assessment and management","issuer":"NICE","scope":"Women with heavy menstrual bleeding considering elective hysterectomy for benign disease; this limited extraction covers anaemia assessment, uterine-cavity investigation, endometrial sampling when indicated and informed surgical decisions.","content":{"id":"78cec019-7976-489a-a4c9-fdd6f7c316c7","title":"Elective Hysterectomy for Benign Disease","specialty":"Gynaecology","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b005","lastReviewed":"2026-10-10","pillar":"Planned Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Hysterectomy removes the uterus and can definitively treat selected benign conditions, but ends fertility and carries operative, urinary, sexual, and recovery implications. Choice of route and alternatives should reflect anatomy, symptoms, risk, and values. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Hysterectomy removes the uterus and can definitively treat selected benign conditions, but ends fertility and carries operative, urinary, sexual, and recovery implications. Choice of route and alternatives should reflect anatomy, symptoms, risk, and values.","Clinical expression and progression vary with baseline risk, comorbidity, treatment exposure, and access to timely care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Elective Hysterectomy for Benign Disease, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Possible pregnancy or unexplained postmenopausal bleeding","Suspicion of malignancy or rapidly changing mass","Severe anaemia or active infection","Uncontrolled cardiopulmonary disease"]},"differentials":[{"condition":"Adenomyosis or endometriosis","distinguishingFeatures":"May coexist and influence pain expectations."},{"condition":"Endometrial hyperplasia/malignancy","distinguishingFeatures":"Requires appropriate diagnostic assessment."},{"condition":"Bleeding disorder","distinguishingFeatures":"Consider with lifelong heavy bleeding or family history."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Pregnancy test when indicated, pelvic examination and imaging; CBC/iron and targeted endometrial evaluation based on age/risk.","modalityTarget":"Pregnancy test when indicated, pelvic examination and imaging; CBC/iron and targeted endometrial evaluation based on age/risk. — Elective Hysterectomy for Benign Disease","targetCondition":"Elective Hysterectomy for Benign Disease","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Preoperative anaesthetic and medication review; route-specific tests follow local policy.","modalityTarget":"Preoperative anaesthetic and medication review; route-specific tests follow local policy. — Cause, complication, or risk relevant to Elective Hysterectomy for Benign Disease","targetCondition":"Cause, complication, or risk relevant to Elective Hysterectomy for Benign Disease","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Elective Hysterectomy for Benign Disease","targetCondition":"Important alternative to Elective Hysterectomy for Benign Disease","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Women with heavy menstrual bleeding considering elective hysterectomy for benign disease; this limited extraction covers anaemia assessment, uterine-cavity investigation, endometrial sampling when indicated and informed surgical decisions. This pathway is limited to heavy menstrual bleeding and does not cover every benign hysterectomy indication, suspected cancer, prolapse, endometriosis or acute bleeding. It requires reconciliation with Saudi gynaecology pathways, cervical screening, pregnancy exclusion, anaesthetic assessment, thrombosis prevention and local consent standards. Pretreatment medicines are mentioned by NICE but no complete regimen or contraindication set is verified here. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"990d3ee1-236f-4497-ad12-4d0b0adb6192","title":"Heavy menstrual bleeding: assessment and management","issuer":"NICE","edition":"NG88, published 14 March 2018; last updated 7 July 2026","url":"https://www.nice.org.uk/guidance/ng88/chapter/Recommendations","locator":"Recommendations 1.2.6, 1.3.3 to 1.3.11, 1.4.4 and 1.4.7 to 1.4.9, plus route and oophorectomy recommendations","primary_source":true}],"selection_rationale":"Unverified scope: Women with heavy menstrual bleeding considering elective hysterectomy for benign disease; this limited extraction covers anaemia assessment, uterine-cavity investigation, endometrial sampling when indicated and informed surgical decisions."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Full blood count","clinical_question":"Is anaemia or another blood-count abnormality present in a woman with heavy menstrual bleeding?","expected_finding":"NICE recommends a full blood count for all women with heavy menstrual bleeding in parallel with treatment.","decision_rationale":"Blood loss and anaemia affect symptoms, optimisation and surgical planning.","timeframe":"During initial assessment and before surgery when clinically required"},{"test":"Outpatient hysteroscopy or pelvic ultrasound selected from history and examination","clinical_question":"Is a submucosal fibroid, polyp, endometrial pathology, adenomyosis or larger fibroid suspected?","expected_finding":"Use outpatient hysteroscopy when cavity pathology is suspected and ultrasound when examination or symptoms indicate larger fibroids, a mass or adenomyosis.","decision_rationale":"Identifying structural disease informs whether hysterectomy and which route are appropriate.","timeframe":"Before definitive surgical planning"},{"test":"Endometrial biopsy at hysteroscopy when high risk","clinical_question":"Is there increased risk of endometrial pathology?","expected_finding":"Consider biopsy during diagnostic hysteroscopy for high-risk women; do not perform blind endometrial biopsy for heavy menstrual bleeding.","decision_rationale":"Targeted sampling improves diagnostic context and avoids unsupported blind sampling.","timeframe":"At diagnostic hysteroscopy when risk criteria are present"}],"evidence":{"sources":[{"id":"990d3ee1-236f-4497-ad12-4d0b0adb6192","title":"Heavy menstrual bleeding: assessment and management","issuer":"NICE","edition":"NG88, published 14 March 2018; last updated 7 July 2026","url":"https://www.nice.org.uk/guidance/ng88/chapter/Recommendations","locator":"Recommendations 1.2.6, 1.3.3 to 1.3.11, 1.4.4 and 1.4.7 to 1.4.9, plus route and oophorectomy recommendations","primary_source":true}],"selection_rationale":"Unverified scope: Women with heavy menstrual bleeding considering elective hysterectomy for benign disease; this limited extraction covers anaemia assessment, uterine-cavity investigation, endometrial sampling when indicated and informed surgical decisions."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Discuss fertility loss, sexual function, bladder function, alternatives, complications, psychological impact, expectations and the possible need for further treatment before deciding on hysterectomy.","timeframe":"Before listing and consent"},{"instruction":"Individualise vaginal, laparoscopic or abdominal route and total versus subtotal hysterectomy; remove ovaries only with the woman's express informed consent after discussing risks and benefits.","timeframe":"During operative planning"},{"instruction":"Review gaps: This pathway is limited to heavy menstrual bleeding and does not cover every benign hysterectomy indication, suspected cancer, prolapse, endometriosis or acute bleeding. It requires reconciliation with Saudi gynaecology pathways, cervical screening, pregnancy exclusion, anaesthetic assessment, thrombosis prevention and local consent standards. Pretreatment medicines are mentioned by NICE but no complete regimen or contraindication set is verified here. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"990d3ee1-236f-4497-ad12-4d0b0adb6192","title":"Heavy menstrual bleeding: assessment and management","issuer":"NICE","edition":"NG88, published 14 March 2018; last updated 7 July 2026","url":"https://www.nice.org.uk/guidance/ng88/chapter/Recommendations","locator":"Recommendations 1.2.6, 1.3.3 to 1.3.11, 1.4.4 and 1.4.7 to 1.4.9, plus route and oophorectomy recommendations","primary_source":true}],"selection_rationale":"Unverified scope: Women with heavy menstrual bleeding considering elective hysterectomy for benign disease; this limited extraction covers anaemia assessment, uterine-cavity investigation, endometrial sampling when indicated and informed surgical decisions."}}]},"nonClinicalManagement":{"patientEducation":["Explain elective hysterectomy for benign disease in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Gynaecology","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"6348dfb9-f42c-4745-b038-ee84d31c521c","title":"Elective Valve Intervention Assessment","original_version_id":"6348dfb9-f42c-4745-b038-ee84d31c521c","expected_hash":"a52dca7247e70daa933214ce0e1a1a6d","source_url":"https://www.nice.org.uk/guidance/ng208/chapter/recommendations","source_title":"Heart valve disease presenting in adults: investigation and management","issuer":"NICE","scope":"Adults with suspected or confirmed heart valve disease being assessed for elective intervention; this limited extraction covers echocardiography, urgent features, severity markers, surveillance and intervention selection.","content":{"id":"6348dfb9-f42c-4745-b038-ee84d31c521c","title":"Elective Valve Intervention Assessment","specialty":"Cardiology / Cardiothoracic Surgery","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b005","lastReviewed":"2026-10-10","pillar":"Planned Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Valve obstruction or regurgitation changes pressure and volume loading, eventually impairing cardiac output and ventricular function. Intervention timing depends on lesion severity, symptoms, cardiac response, procedural risk, and expected benefit. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Valve obstruction or regurgitation changes pressure and volume loading, eventually impairing cardiac output and ventricular function. Intervention timing depends on lesion severity, symptoms, cardiac response, procedural risk, and expected benefit.","Clinical expression and progression vary with baseline risk, comorbidity, treatment exposure, and access to timely care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Elective Valve Intervention Assessment, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Syncope or exertional chest pain with severe stenosis","Pulmonary oedema or decompensated heart failure","Endocarditis concern or embolic event","Rapid decline in ventricular function"]},"differentials":[{"condition":"Coronary artery disease","distinguishingFeatures":"May coexist and contribute to symptoms."},{"condition":"Lung disease or anaemia","distinguishingFeatures":"Can explain exercise limitation but does not negate severe valve disease."},{"condition":"HFpEF or deconditioning","distinguishingFeatures":"Multifactorial symptoms need structured review."}],"investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Comprehensive echocardiography, ECG, functional status, renal function, frailty and coronary assessment as indicated.","modalityTarget":"Comprehensive echocardiography, ECG, functional status, renal function, frailty and coronary assessment as indicated. — Elective Valve Intervention Assessment","targetCondition":"Elective Valve Intervention Assessment","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Use current local Heart Team pathway to select timing and intervention.","modalityTarget":"Use current local Heart Team pathway to select timing and intervention. — Cause, complication, or risk relevant to Elective Valve Intervention Assessment","targetCondition":"Cause, complication, or risk relevant to Elective Valve Intervention Assessment","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Elective Valve Intervention Assessment","targetCondition":"Important alternative to Elective Valve Intervention Assessment","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults with suspected or confirmed heart valve disease being assessed for elective intervention; this limited extraction covers echocardiography, urgent features, severity markers, surveillance and intervention selection. NICE states that its TAVI recommendations are under review, creating a current-edition conflict that must be reconciled before approval. This UK guidance also requires Saudi Heart Team policy, local surgical-risk assessment, CT planning, coronary assessment, frailty, life expectancy, pregnancy and prosthesis-anticoagulation pathways. No medicine or antithrombotic regimen is verified. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"d57aa86a-d060-4e37-8c72-22f915bb14ed","title":"Heart valve disease presenting in adults: investigation and management","issuer":"NICE","edition":"NG208, published 17 November 2021; reviewed 24 October 2025 with a TAVI update in development","url":"https://www.nice.org.uk/guidance/ng208/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.1.8, 1.3.1 to 1.3.11, 1.4.1 and 1.5.1 to 1.5.13","primary_source":true}],"selection_rationale":"Unverified scope: Adults with suspected or confirmed heart valve disease being assessed for elective intervention; this limited extraction covers echocardiography, urgent features, severity markers, surveillance and intervention selection."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Transthoracic echocardiography","clinical_question":"Is valve disease present and how severe is it?","expected_finding":"Offer echocardiography when a suspicious murmur is accompanied by symptoms, signs or an abnormal ECG, and use it to quantify valve lesion, ventricular response and intervention thresholds.","decision_rationale":"Valve anatomy and haemodynamic severity drive specialist referral and timing.","timeframe":"At diagnostic assessment; urgently when high-risk symptoms are present"},{"test":"Urgent specialist assessment for high-risk symptoms","clinical_question":"Are exertional syncope, severe breathlessness or angina likely related to valve disease?","expected_finding":"A systolic murmur with exertional syncope warrants specialist assessment including echocardiography within 2 weeks; severe symptoms also warrant urgent assessment.","decision_rationale":"These features can indicate severe disease with elevated short-term risk.","timeframe":"Within 2 weeks"},{"test":"Intervention-threshold assessment","clinical_question":"Do symptoms, valve severity, ventricular function, exercise testing, natriuretic peptides or CT findings indicate intervention?","expected_finding":"NICE uses lesion-specific echo thresholds and, for selected aortic stenosis, exercise testing, BNP or NT-proBNP, dobutamine stress echo, calcium score and cardiac MRI.","decision_rationale":"Multimodal assessment identifies asymptomatic people whose risk may justify intervention and clarifies uncertain severity.","timeframe":"Before Heart Team decision"}],"evidence":{"sources":[{"id":"d57aa86a-d060-4e37-8c72-22f915bb14ed","title":"Heart valve disease presenting in adults: investigation and management","issuer":"NICE","edition":"NG208, published 17 November 2021; reviewed 24 October 2025 with a TAVI update in development","url":"https://www.nice.org.uk/guidance/ng208/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.1.8, 1.3.1 to 1.3.11, 1.4.1 and 1.5.1 to 1.5.13","primary_source":true}],"selection_rationale":"Unverified scope: Adults with suspected or confirmed heart valve disease being assessed for elective intervention; this limited extraction covers echocardiography, urgent features, severity markers, surveillance and intervention selection."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Offer intervention to adults with symptomatic severe valve disease and select surgery, transcatheter intervention or conservative management through shared specialist assessment.","timeframe":"After severity and suitability assessment"},{"instruction":"For asymptomatic severe valve disease suitable for intervention but without a current indication, provide clinical review with echocardiography every 6 to 12 months, adjusted to findings and shared decisions.","timeframe":"Every 6 to 12 months"},{"instruction":"Review gaps: NICE states that its TAVI recommendations are under review, creating a current-edition conflict that must be reconciled before approval. This UK guidance also requires Saudi Heart Team policy, local surgical-risk assessment, CT planning, coronary assessment, frailty, life expectancy, pregnancy and prosthesis-anticoagulation pathways. No medicine or antithrombotic regimen is verified. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"d57aa86a-d060-4e37-8c72-22f915bb14ed","title":"Heart valve disease presenting in adults: investigation and management","issuer":"NICE","edition":"NG208, published 17 November 2021; reviewed 24 October 2025 with a TAVI update in development","url":"https://www.nice.org.uk/guidance/ng208/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.1.8, 1.3.1 to 1.3.11, 1.4.1 and 1.5.1 to 1.5.13","primary_source":true}],"selection_rationale":"Unverified scope: Adults with suspected or confirmed heart valve disease being assessed for elective intervention; this limited extraction covers echocardiography, urgent features, severity markers, surveillance and intervention selection."}}]},"nonClinicalManagement":{"patientEducation":["Explain elective valve intervention assessment in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Cardiology / Cardiothoracic Surgery","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"cbf215a8-cc12-4b87-a821-cef2f005f43c","title":"Fetal Growth Restriction Assessment","original_version_id":"cbf215a8-cc12-4b87-a821-cef2f005f43c","expected_hash":"56e67075a3f7d8cabdbcb04e65625b80","source_url":"https://www.rcog.org.uk/gtg31","source_title":"Investigation and Care of a Small-for-Gestational-Age Fetus and a Growth Restricted Fetus","issuer":"Other","scope":"Singleton pregnancies at low, moderate or high risk of a small-for-gestational-age fetus or fetal growth restriction; multiple pregnancy and fetal anomaly are outside the source scope.","content":{"id":"cbf215a8-cc12-4b87-a821-cef2f005f43c","title":"Fetal Growth Restriction Assessment","specialty":"Maternal-Fetal Medicine","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b005","lastReviewed":"2026-10-10","pillar":"Safe Birth","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Placental insufficiency can restrict oxygen and nutrient delivery, altering fetal growth and increasing stillbirth and neonatal risk. Maternal vascular disease, fetal anomalies, infection, and inaccurate dating are important alternatives. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Placental insufficiency can restrict oxygen and nutrient delivery, altering fetal growth and increasing stillbirth and neonatal risk. Maternal vascular disease, fetal anomalies, infection, and inaccurate dating are important alternatives.","Clinical expression and progression vary with baseline risk, comorbidity, treatment exposure, and access to timely care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Fetal Growth Restriction Assessment, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Absent/reversed end-diastolic flow","Reduced fetal movement or non-reassuring testing","Severe maternal hypertension or placental abruption","Growth restriction with major anomaly or infection concern"]},"differentials":[{"condition":"Constitutionally small fetus","distinguishingFeatures":"Stable growth and normal placental assessment may support this."},{"condition":"Incorrect dating","distinguishingFeatures":"Early dating record is important."},{"condition":"Congenital anomaly or infection","distinguishingFeatures":"Targeted assessment based on findings."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Review dating and serial biometry, amniotic fluid and umbilical artery Doppler; assess maternal blood pressure and relevant comorbidity.","modalityTarget":"Review dating and serial biometry, amniotic fluid and umbilical artery Doppler; assess maternal blood pressure and relevant comorbidity. — Fetal Growth Restriction Assessment","targetCondition":"Fetal Growth Restriction Assessment","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Additional fetal surveillance and delivery timing follow current local maternal-fetal protocol.","modalityTarget":"Additional fetal surveillance and delivery timing follow current local maternal-fetal protocol. — Cause, complication, or risk relevant to Fetal Growth Restriction Assessment","targetCondition":"Cause, complication, or risk relevant to Fetal Growth Restriction Assessment","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Fetal Growth Restriction Assessment","targetCondition":"Important alternative to Fetal Growth Restriction Assessment","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Singleton pregnancies at low, moderate or high risk of a small-for-gestational-age fetus or fetal growth restriction; multiple pregnancy and fetal anomaly are outside the source scope. The July 2026 correction warns against Intergrowth-21 estimated-fetal-weight charts in the NHS population; chart selection must be reconciled with Saudi population validation and local maternity policy. Aspirin 150 mg nightly from 12+0 to 36+0 weeks is supported for women at risk of pre-eclampsia or placental dysfunction, but the linked recommendation does not state route or a complete contraindication and interaction set, so no medication regimen is encoded. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"afb21956-978b-4ac5-b258-dd7c7abd8af6","title":"Investigation and Care of a Small-for-Gestational-Age Fetus and a Growth Restricted Fetus","issuer":"Other","edition":"RCOG Green-top Guideline No. 31, third edition, first published 13 May 2024; correction/update noted July 2026","url":"https://www.rcog.org.uk/gtg31","locator":"Official RCOG landing page and linked full-text key recommendations; risk assessment by 14 weeks, uterine artery Doppler, serial biometry, umbilical artery Doppler and birth-timing recommendations","primary_source":true}],"selection_rationale":"Unverified scope: Singleton pregnancies at low, moderate or high risk of a small-for-gestational-age fetus or fetal growth restriction; multiple pregnancy and fetal anomaly are outside the source scope."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Structured fetal-growth-restriction risk assessment","clinical_question":"Does maternal medical, obstetric or current-pregnancy history require enhanced surveillance?","expected_finding":"RCOG recommends assessment at booking by 14 weeks and updating risk after the anomaly scan and throughout pregnancy.","decision_rationale":"Early risk classification determines whether fundal-height surveillance, uterine artery Doppler or serial ultrasound is needed.","timeframe":"By 14 weeks, after the mid-trimester scan and whenever risk changes"},{"test":"Uterine artery Doppler for high-risk pregnancy","clinical_question":"Is there evidence of increased placental resistance?","expected_finding":"For high-risk women, perform uterine artery Doppler between 18+0 and 23+6 weeks; abnormal mean pulsatility index above the 95th centile leads to earlier serial growth scans.","decision_rationale":"Placental Doppler stratifies surveillance timing for growth disorders.","timeframe":"18+0 to 23+6 weeks"},{"test":"Serial fetal biometry and umbilical artery Doppler","clinical_question":"Is fetal size or growth trajectory abnormal and is there placental compromise?","expected_finding":"Once SGA is identified, repeat biometry every 2 weeks and perform umbilical artery Doppler at diagnosis and at least every 2 weeks.","decision_rationale":"Serial size, growth velocity and Doppler distinguish constitutional smallness from fetal growth restriction and guide birth timing.","timeframe":"At diagnosis and at least every 2 weeks"}],"evidence":{"sources":[{"id":"afb21956-978b-4ac5-b258-dd7c7abd8af6","title":"Investigation and Care of a Small-for-Gestational-Age Fetus and a Growth Restricted Fetus","issuer":"Other","edition":"RCOG Green-top Guideline No. 31, third edition, first published 13 May 2024; correction/update noted July 2026","url":"https://www.rcog.org.uk/gtg31","locator":"Official RCOG landing page and linked full-text key recommendations; risk assessment by 14 weeks, uterine artery Doppler, serial biometry, umbilical artery Doppler and birth-timing recommendations","primary_source":true}],"selection_rationale":"Unverified scope: Singleton pregnancies at low, moderate or high risk of a small-for-gestational-age fetus or fetal growth restriction; multiple pregnancy and fetal anomaly are outside the source scope."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"For women at risk of pre-eclampsia or placental dysfunction, the RCOG recommendation is aspirin 150 mg once daily at night from 12+0 to 36+0 weeks; confirm route, contraindications, interactions and local policy before prescribing.","timeframe":"12+0 to 36+0 weeks"},{"instruction":"Escalate early FGR before 32 weeks to tertiary multidisciplinary fetal-medicine and neonatal care; base birth timing on gestation, Doppler, growth, CTG, maternal condition and the guideline's lesion-specific recommendations.","timeframe":"At diagnosis and with any deterioration"},{"instruction":"Review gaps: The July 2026 correction warns against Intergrowth-21 estimated-fetal-weight charts in the NHS population; chart selection must be reconciled with Saudi population validation and local maternity policy. Aspirin 150 mg nightly from 12+0 to 36+0 weeks is supported for women at risk of pre-eclampsia or placental dysfunction, but the linked recommendation does not state route or a complete contraindication and interaction set, so no medication regimen is encoded. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"afb21956-978b-4ac5-b258-dd7c7abd8af6","title":"Investigation and Care of a Small-for-Gestational-Age Fetus and a Growth Restricted Fetus","issuer":"Other","edition":"RCOG Green-top Guideline No. 31, third edition, first published 13 May 2024; correction/update noted July 2026","url":"https://www.rcog.org.uk/gtg31","locator":"Official RCOG landing page and linked full-text key recommendations; risk assessment by 14 weeks, uterine artery Doppler, serial biometry, umbilical artery Doppler and birth-timing recommendations","primary_source":true}],"selection_rationale":"Unverified scope: Singleton pregnancies at low, moderate or high risk of a small-for-gestational-age fetus or fetal growth restriction; multiple pregnancy and fetal anomaly are outside the source scope."}}]},"nonClinicalManagement":{"patientEducation":["Explain fetal growth restriction assessment in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Maternal-Fetal Medicine","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"e58a1236-9f75-4ca4-a398-0e27b5c1f849","title":"Gestational Diabetes Identification and Management Pathway","original_version_id":"e58a1236-9f75-4ca4-a398-0e27b5c1f849","expected_hash":"929977fa8a24ea723c5c46277c4ab47a","source_url":"https://www.nice.org.uk/guidance/NG3/chapter/recommendations","source_title":"Diabetes in pregnancy: management from preconception to the postnatal period","issuer":"NICE","scope":"Pregnant women being assessed for or diagnosed with gestational diabetes; this limited extraction covers risk-based OGTT, diagnostic thresholds, early review, glucose targets and treatment escalation.","content":{"id":"e58a1236-9f75-4ca4-a398-0e27b5c1f849","title":"Gestational Diabetes Identification and Management Pathway","specialty":"Obstetrics, Maternal-Fetal Medicine, and Diabetes Care","authority":"MOH","status":"draft","version":"official-extraction-2026-10-11-b005","lastReviewed":"2026-10-10","pillar":"Safe Birth","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Gestational diabetes is glucose intolerance first recognised during pregnancy. Pregnancy-related insulin resistance may exceed pancreatic insulin-secretory capacity, increasing maternal glucose and fetal exposure.","keyMechanisms":["Placental hormones increase maternal insulin resistance","Insufficient compensatory insulin secretion leads to hyperglycaemia","Maternal glucose crosses the placenta and may affect fetal growth and perinatal risk"]},"presentation":{"symptoms":["Often asymptomatic and detected through antenatal screening","Possible increased thirst or urination, which may overlap with normal pregnancy changes"],"physicalSigns":["Usually no specific examination finding","Risk factors may include previous gestational diabetes, prior macrosomia, obesity, or family history"],"redFlags":["Marked hyperglycaemia with vomiting, dehydration, altered mental status, or ketones","Reduced fetal movement, bleeding, or severe abdominal pain","Symptoms concerning for pre-eclampsia"]},"differentials":[{"condition":"Previously unrecognised pre-existing diabetes","distinguishingFeatures":"Hyperglycaemia meeting overt diabetes criteria early in pregnancy or evidence predating pregnancy."},{"condition":"Transient stress hyperglycaemia","distinguishingFeatures":"Elevated glucose during acute illness or medication exposure; interpret timing and repeat as appropriate."},{"condition":"Normal pregnancy-related changes","distinguishingFeatures":"Thirst or urinary frequency without diagnostic hyperglycaemia; symptoms alone do not establish GDM."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Pregnancy-specific oral glucose tolerance test using local protocol","modalityTarget":"Pregnancy-specific oral glucose tolerance test using local protocol — Gestational diabetes","targetCondition":"Gestational diabetes","expectedFinding":"One or more glucose values meet locally adopted diagnostic thresholds","clinicalRationale":"Apply the approved screening and diagnostic protocol consistently."},{"tier":"laboratory","testName":"Laboratory fasting or random plasma glucose when indicated","modalityTarget":"Laboratory fasting or random plasma glucose when indicated — Overt diabetes in pregnancy","targetCondition":"Overt diabetes in pregnancy","expectedFinding":"Value meets accepted overt-diabetes criteria or local pregnancy pathway","clinicalRationale":"Identify significant hyperglycaemia that may represent pre-existing diabetes."},{"tier":"laboratory","testName":"Serial self-monitored blood glucose","modalityTarget":"Serial self-monitored blood glucose — Glycaemic control during pregnancy","targetCondition":"Glycaemic control during pregnancy","expectedFinding":"Repeated readings outside individualised targets","clinicalRationale":"Guide timely adjustment and assess response."},{"tier":"specializedAdjunctive","testName":"Obstetric ultrasound when indicated","modalityTarget":"Obstetric ultrasound when indicated — Fetal growth or fluid concern","targetCondition":"Fetal growth or fluid concern","expectedFinding":"Growth or fluid finding requiring obstetric review","clinicalRationale":"Assess pregnancy concerns and guide obstetric planning."}],"ruleOut":[{"tier":"laboratory","testName":"Pregnancy-specific oral glucose tolerance test using local protocol","modalityTarget":"Pregnancy-specific oral glucose tolerance test using local protocol — Gestational diabetes","targetCondition":"Gestational diabetes","expectedFinding":"All measured values below adopted diagnostic thresholds","clinicalRationale":"A correctly timed test can exclude GDM at that screening point."},{"tier":"laboratory","testName":"Repeat glucose assessment when initial testing is incomplete or concern persists","modalityTarget":"Repeat glucose assessment when initial testing is incomplete or concern persists — Missed or evolving gestational hyperglycaemia","targetCondition":"Missed or evolving gestational hyperglycaemia","expectedFinding":"Repeat values below diagnostic thresholds under appropriate protocol","clinicalRationale":"Consider timing, risk, test quality, and evolving pregnancy."}]},"clinicalManagement":[{"id":"gdm-1","title":"Screen, diagnose, and communicate","timeframe":"At timing defined by local antenatal protocol","actions":["Review diabetes history, prior GDM, pregnancy history, medicines, and risk factors.","Use the locally adopted pregnancy-specific screening and diagnostic protocol.","Distinguish GDM from overt pre-existing diabetes when early or marked hyperglycaemia is found.","Communicate results promptly to patient and antenatal team."],"branches":[{"condition":"Overt diabetes, severe hyperglycaemia, or acute metabolic illness suspected","actions":["Arrange urgent obstetric-diabetes or emergency assessment based on status.","Use pregnancy-specific acute management guidance."]},{"condition":"GDM diagnosed without acute instability","actions":["Refer promptly to obstetric-diabetes care.","Provide initial education and arrange monitoring and review."]}]},{"id":"gdm-2","title":"Monitor glucose and individualise treatment","timeframe":"From diagnosis through pregnancy","actions":["Teach self-monitoring and agree pregnancy-specific targets with the team.","Offer nutrition counselling and safe activity advice.","Review glucose records, symptoms, treatment tolerance, and obstetric concerns.","If targets are unmet, consider pregnancy-appropriate medicines under local protocol and specialist care."],"branches":[{"condition":"Values remain above agreed targets","actions":["Review technique, nutrition, adherence barriers, and intercurrent illness.","Escalate treatment under pregnancy-specific local guidance."]},{"condition":"Reduced fetal movement or another obstetric warning symptom","actions":["Arrange immediate maternity triage or emergency assessment.","Do not defer assessment to routine diabetes follow-up."]}]},{"id":"gdm-3","title":"Plan birth and postpartum reassessment","timeframe":"Later pregnancy, birth, and after delivery","actions":["Coordinate timing and place of birth based on maternal control and fetal assessment.","Document intrapartum glucose and newborn-care plans under local policy.","Review glucose-lowering treatment after delivery as requirements may change.","Arrange postpartum testing and longer-term primary-care follow-up."],"branches":[{"condition":"Persistent postpartum hyperglycaemia or pre-existing diabetes concern","actions":["Arrange timely medical assessment and diagnostic testing.","Continue the appropriate diabetes-care pathway."]},{"condition":"Glucose normalises after birth","actions":["Still arrange postpartum testing at the locally recommended interval.","Discuss future risk reduction and screening in subsequent pregnancies."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Pregnant women being assessed for or diagnosed with gestational diabetes; this limited extraction covers risk-based OGTT, diagnostic thresholds, early review, glucose targets and treatment escalation. This older UK recommendation uses NICE diagnostic thresholds that may differ from WHO, IADPSG or current Saudi pathways. It must be reconciled with Saudi antenatal screening strategy, laboratory standards and medicine formulary. Metformin and insulin are named, but exact product, dose, route, frequency, titration, duration and complete contraindications are not supplied in the selected recommendations, so no medication regimen is encoded. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"f7d201b5-d491-4ca5-83dd-f11c99a1a9fd","title":"Diabetes in pregnancy: management from preconception to the postnatal period","issuer":"NICE","edition":"NG3, published 25 February 2015; last updated 16 December 2020","url":"https://www.nice.org.uk/guidance/NG3/chapter/recommendations","locator":"Recommendations 1.2.1 to 1.2.23 and 1.3.1 to 1.3.6","primary_source":true}],"selection_rationale":"Unverified scope: Pregnant women being assessed for or diagnosed with gestational diabetes; this limited extraction covers risk-based OGTT, diagnostic thresholds, early review, glucose targets and treatment escalation."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Gestational-diabetes risk-factor assessment","clinical_question":"Is risk-based diagnostic testing indicated?","expected_finding":"At booking, assess BMI 30 kg/m² or above, previous baby 4.5 kg or above, previous gestational diabetes, first-degree family history and high-prevalence ethnicity.","decision_rationale":"NICE uses these factors to select women for diagnostic testing.","timeframe":"At the booking appointment"},{"test":"75 g 2-hour oral glucose tolerance test","clinical_question":"Does the woman meet NICE criteria for gestational diabetes?","expected_finding":"Diagnose if fasting plasma glucose is 5.6 mmol/L or above or the 2-hour value is 7.8 mmol/L or above.","decision_rationale":"The OGTT and specified thresholds establish diagnosis in the source pathway.","timeframe":"At 24 to 28 weeks for risk factors; earlier after booking for previous gestational diabetes, repeating at 24 to 28 weeks if initially normal"},{"test":"Capillary glucose self-monitoring","clinical_question":"Are individualised pregnancy glucose targets being met without problematic hypoglycaemia?","expected_finding":"NICE targets are fasting below 5.3 mmol/L, 1-hour post-meal below 7.8 mmol/L or 2-hour post-meal below 6.4 mmol/L; insulin-treated women should stay above 4 mmol/L.","decision_rationale":"Frequent glucose data guide escalation and reduce maternal and fetal risk.","timeframe":"Daily after diagnosis according to treatment regimen"}],"evidence":{"sources":[{"id":"f7d201b5-d491-4ca5-83dd-f11c99a1a9fd","title":"Diabetes in pregnancy: management from preconception to the postnatal period","issuer":"NICE","edition":"NG3, published 25 February 2015; last updated 16 December 2020","url":"https://www.nice.org.uk/guidance/NG3/chapter/recommendations","locator":"Recommendations 1.2.1 to 1.2.23 and 1.3.1 to 1.3.6","primary_source":true}],"selection_rationale":"Unverified scope: Pregnant women being assessed for or diagnosed with gestational diabetes; this limited extraction covers risk-based OGTT, diagnostic thresholds, early review, glucose targets and treatment escalation."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Arrange review in a joint diabetes and antenatal clinic within 1 week of diagnosis and refer to a dietitian.","timeframe":"Within 1 week"},{"instruction":"If fasting glucose is below 7.0 mmol/L at diagnosis, offer diet and exercise initially; if targets are not met within 1 to 2 weeks, offer metformin, or insulin if metformin is contraindicated or unacceptable.","timeframe":"Review response within 1 to 2 weeks"},{"instruction":"If fasting glucose is 7.0 mmol/L or above at diagnosis, offer immediate insulin with or without metformin plus diet and exercise changes.","timeframe":"Immediately after diagnosis"},{"instruction":"Review gaps: This older UK recommendation uses NICE diagnostic thresholds that may differ from WHO, IADPSG or current Saudi pathways. It must be reconciled with Saudi antenatal screening strategy, laboratory standards and medicine formulary. Metformin and insulin are named, but exact product, dose, route, frequency, titration, duration and complete contraindications are not supplied in the selected recommendations, so no medication regimen is encoded. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"f7d201b5-d491-4ca5-83dd-f11c99a1a9fd","title":"Diabetes in pregnancy: management from preconception to the postnatal period","issuer":"NICE","edition":"NG3, published 25 February 2015; last updated 16 December 2020","url":"https://www.nice.org.uk/guidance/NG3/chapter/recommendations","locator":"Recommendations 1.2.1 to 1.2.23 and 1.3.1 to 1.3.6","primary_source":true}],"selection_rationale":"Unverified scope: Pregnant women being assessed for or diagnosed with gestational diabetes; this limited extraction covers risk-based OGTT, diagnostic thresholds, early review, glucose targets and treatment escalation."}}]},"nonClinicalManagement":{"patientEducation":["Explain GDM, monitoring, and how results guide parent and baby care.","Teach monitoring and whom to contact for repeated out-of-range readings.","Provide maternity warning signs including reduced fetal movement."],"lifestyleAndDiet":["Offer culturally appropriate nutrition advice supporting pregnancy and glucose management.","Encourage safe regular activity when not contraindicated.","Avoid restrictive diets or weight-loss advice during pregnancy unless directed by the team."],"mdtReferrals":["Obstetric or maternal-fetal medicine team","Diabetes nurse or educator","Dietitian","Neonatal team when indicated","Primary care or diabetes service postpartum"],"dischargeCriteria":["Maternal and fetal status are appropriate for planned setting.","Patient has monitoring instructions, contact routes, and follow-up plan.","Postpartum testing responsibilities are documented before birth discharge."],"followUpPlan":"Continue antenatal review based on glucose control and obstetric risk; arrange postpartum testing according to local protocol and ongoing primary-care screening."}}},{"id":"35d6fe28-9862-4850-a9ea-7f1d24306001","title":"Heart Failure","original_version_id":"35d6fe28-9862-4850-a9ea-7f1d24306001","expected_hash":"07e4a905aba6dee8f3c6588c52c9a069","source_url":"https://www.nice.org.uk/guidance/ng106/chapter/recommendations","source_title":"Chronic heart failure in adults: diagnosis and management","issuer":"NICE","scope":"Adults with suspected or established chronic heart failure; this limited extraction covers NT-proBNP referral thresholds, echocardiography, phenotype classification and selected pre-treatment safety checks.","content":{"id":"35d6fe28-9862-4850-a9ea-7f1d24306001","title":"Heart Failure","specialty":"Cardiology / Primary Care","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b005","lastReviewed":"2026-10-10","pillar":"Chronic Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Structural or functional cardiac impairment raises filling pressures and/or limits output. Neurohormonal activation and remodelling contribute to progression; phenotype and comorbidity guide treatment choices. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Structural or functional cardiac impairment raises filling pressures and/or limits output. Neurohormonal activation and remodelling contribute to progression","phenotype and comorbidity guide treatment choices."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Heart Failure, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Syncope, rest dyspnoea, or rapidly increasing oedema","Chest pain or new arrhythmia","Hypotension, cool peripheries, or reduced urine output","New confusion or acute kidney dysfunction"]},"differentials":[{"condition":"COPD/asthma","distinguishingFeatures":"May coexist; respiratory phenotype and congestion assessment help separate contributions."},{"condition":"Renal fluid overload","distinguishingFeatures":"Kidney trajectory and volume status guide attribution."},{"condition":"Anaemia, thyroid disease, ischaemia, or arrhythmia","distinguishingFeatures":"Can mimic or worsen functional decline."}],"investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Review echocardiogram, ECG, renal function/electrolytes, blood count, iron status and natriuretic peptide as appropriate.","modalityTarget":"Review echocardiogram, ECG, renal function/electrolytes, blood count, iron status and natriuretic peptide as appropriate. — Heart Failure","targetCondition":"Heart Failure","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Assess symptoms, admissions, volume status, medication tolerance, and comorbid disease.","modalityTarget":"Assess symptoms, admissions, volume status, medication tolerance, and comorbid disease. — Cause, complication, or risk relevant to Heart Failure","targetCondition":"Cause, complication, or risk relevant to Heart Failure","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Heart Failure","targetCondition":"Important alternative to Heart Failure","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults with suspected or established chronic heart failure; this limited extraction covers NT-proBNP referral thresholds, echocardiography, phenotype classification and selected pre-treatment safety checks. This UK guideline requires reconciliation with current Saudi heart-failure pathways, local natriuretic-peptide assays and access to specialist care. NICE names core HFrEF medicine classes and newer HFmrEF/HFpEF options but does not provide a complete product-specific dose, route, frequency, titration, duration and contraindication set in the selected recommendations, so no medication regimen is encoded. Acute decompensated heart failure is outside scope. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"b47f83cf-2c7c-4e3a-9f5e-5877049ddca7","title":"Chronic heart failure in adults: diagnosis and management","issuer":"NICE","edition":"NG106, published 12 September 2018; last updated 3 September 2025","url":"https://www.nice.org.uk/guidance/ng106/chapter/recommendations","locator":"Recommendations 1.2.1 to 1.2.12, 1.4.1 to 1.5.3 and 1.7.1 to 1.7.11","primary_source":true}],"selection_rationale":"Unverified scope: Adults with suspected or established chronic heart failure; this limited extraction covers NT-proBNP referral thresholds, echocardiography, phenotype classification and selected pre-treatment safety checks."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"NT-proBNP","clinical_question":"Does suspected chronic heart failure require urgent or routine specialist assessment?","expected_finding":"More than 2,000 ng/L warrants specialist assessment and transthoracic echocardiography within 2 weeks; 400 to 2,000 ng/L warrants both within 6 weeks; below 400 ng/L in an untreated person makes heart failure less likely.","decision_rationale":"Natriuretic-peptide level supports referral urgency and identifies when alternative causes should be reviewed.","timeframe":"At initial assessment; referral within 2 or 6 weeks according to result"},{"test":"Transthoracic echocardiography","clinical_question":"Is there valve disease, systolic or diastolic dysfunction or an intracardiac shunt?","expected_finding":"Echocardiography defines structural disease and ventricular phenotype for specialist diagnosis and treatment.","decision_rationale":"Treatment differs for reduced, mildly reduced and preserved ejection fraction and for valve disease.","timeframe":"Within the NT-proBNP-directed referral window"},{"test":"12-lead electrocardiogram before beta-blocker consideration","clinical_question":"Is bradycardia, heart block or another rhythm or conduction abnormality present?","expected_finding":"Assess rhythm, rate and conduction before prescribing; do not offer a beta-blocker for heart rate below 50 beats/minute or second- or third-degree heart block without a pacemaker.","decision_rationale":"Baseline conduction assessment identifies a source-defined contraindication to beta-blocker use.","timeframe":"Before beta-blocker initiation and after dose increments when symptomatic bradycardia requires review"}],"evidence":{"sources":[{"id":"b47f83cf-2c7c-4e3a-9f5e-5877049ddca7","title":"Chronic heart failure in adults: diagnosis and management","issuer":"NICE","edition":"NG106, published 12 September 2018; last updated 3 September 2025","url":"https://www.nice.org.uk/guidance/ng106/chapter/recommendations","locator":"Recommendations 1.2.1 to 1.2.12, 1.4.1 to 1.5.3 and 1.7.1 to 1.7.11","primary_source":true}],"selection_rationale":"Unverified scope: Adults with suspected or established chronic heart failure; this limited extraction covers NT-proBNP referral thresholds, echocardiography, phenotype classification and selected pre-treatment safety checks."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Refer newly diagnosed, recently decompensated or advanced heart failure to the specialist multidisciplinary team for diagnosis and treatment optimisation.","timeframe":"After suspected or confirmed diagnosis"},{"instruction":"For HFrEF, NICE recommends an ACE inhibitor, beta-blocker, mineralocorticoid-receptor antagonist and SGLT2 inhibitor, introduced and monitored according to the source and product-specific guidance; do not use this limited draft as a prescribing protocol.","timeframe":"After specialist phenotype and safety assessment"},{"instruction":"Review gaps: This UK guideline requires reconciliation with current Saudi heart-failure pathways, local natriuretic-peptide assays and access to specialist care. NICE names core HFrEF medicine classes and newer HFmrEF/HFpEF options but does not provide a complete product-specific dose, route, frequency, titration, duration and contraindication set in the selected recommendations, so no medication regimen is encoded. Acute decompensated heart failure is outside scope. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"b47f83cf-2c7c-4e3a-9f5e-5877049ddca7","title":"Chronic heart failure in adults: diagnosis and management","issuer":"NICE","edition":"NG106, published 12 September 2018; last updated 3 September 2025","url":"https://www.nice.org.uk/guidance/ng106/chapter/recommendations","locator":"Recommendations 1.2.1 to 1.2.12, 1.4.1 to 1.5.3 and 1.7.1 to 1.7.11","primary_source":true}],"selection_rationale":"Unverified scope: Adults with suspected or established chronic heart failure; this limited extraction covers NT-proBNP referral thresholds, echocardiography, phenotype classification and selected pre-treatment safety checks."}}]},"nonClinicalManagement":{"patientEducation":["Explain heart failure in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Cardiology / Primary Care","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}}]$population$)
as x(id uuid,title text,original_version_id uuid,expected_hash text,source_url text,source_title text,issuer text,scope text,content jsonb);
